// Wrong-script / mojibake scan of one Lokalise project (+ language chunk). READ ONLY.
// Flags TARGET translations that contain characters from a writing system the target
// language does not use (e.g. Chinese 谋 inside Turkish "haz谋r!"), or classic encoding
// garbage (Ã©, â€™, Ä±, U+FFFD). Latin is always allowed (brand names, formats).
const inp = $('When called').first().json;
const base = String(inp.base_iso || 'en').toLowerCase();
const pages = $input.all().map(function (i) { return i.json || {}; });
let keys = []; let err = null;
for (const p of pages) {
  if (p.statusCode && p.statusCode !== 200) { err = 'HTTP ' + p.statusCode + ' ' + JSON.stringify(p.body || '').slice(0, 200); continue; }
  const b = p.body || p;
  if (Array.isArray(b.keys)) { keys = keys.concat(b.keys); }
  else if (!err) { err = 'no keys array: ' + JSON.stringify(b).slice(0, 200); }
}
const SCRIPTS = ['Han','Hiragana','Katakana','Hangul','Cyrillic','Greek','Arabic','Hebrew','Thai','Devanagari','Georgian','Armenian','Bengali','Tamil','Ethiopic','Khmer','Lao','Myanmar'];
const RX = {}; for (const s of SCRIPTS) { RX[s] = new RegExp('\\p{Script=' + s + '}', 'u'); }
const ALLOW = { el: ['Greek'], uk: ['Cyrillic'], ru: ['Cyrillic'], bg: ['Cyrillic'], sr: ['Cyrillic'], mk: ['Cyrillic'], kk: ['Cyrillic'], be: ['Cyrillic'], mn: ['Cyrillic'],
  ja: ['Han','Hiragana','Katakana'], zh: ['Han'], ko: ['Hangul','Han'], th: ['Thai'], ar: ['Arabic'], fa: ['Arabic'], ur: ['Arabic'], he: ['Hebrew'], hi: ['Devanagari'], mr: ['Devanagari'], ne: ['Devanagari'],
  ka: ['Georgian'], hy: ['Armenian'], bn: ['Bengali'], ta: ['Tamil'], am: ['Ethiopic'], km: ['Khmer'], lo: ['Lao'], my: ['Myanmar'] };
const MOJI = /[ÃÂÄÅÐÑ][\u0080-\u009F\u00A1-\u00BF]|â€|ï¿½|\uFFFD/g;
const PSEUDO = /^(pst|ps|xx|zz|qps)$|pseudo|[_-]ps$/i;
function lang(iso) { return String(iso || '').toLowerCase().split(/[-_]/)[0]; }
function scriptOf(ch) { for (const s of SCRIPTS) { if (RX[s].test(ch)) { return s; } } return null; }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || n.ios || n.android || ''); }
const hits = [];
for (const k of keys) {
  if (k.is_archived) { continue; }
  const trs = (k.translations || []).filter(function (t) { return typeof t.translation === 'string' && t.translation.trim(); });
  let src = '';
  for (const t of trs) { if (String(t.language_iso).toLowerCase() === base) { src = t.translation; } }
  // characters per locale, to spot intentional cross-locale text (e.g. native language names)
  const charLocs = {};
  for (const t of trs) { for (const ch of new Set(Array.from(t.translation))) { if (ch.charCodeAt(0) > 0x2FF) { charLocs[ch] = (charLocs[ch] || 0) + 1; } } }
  for (const t of trs) {
    const iso = String(t.language_iso || '').toLowerCase();
    if (iso === base || PSEUDO.test(iso)) { continue; }
    const allow = ALLOW[lang(iso)] || [];
    const bad = {};
    for (const ch of Array.from(t.translation)) {
      if (ch.charCodeAt(0) < 0x370) { continue; }
      const s = scriptOf(ch);
      if (!s || allow.indexOf(s) !== -1) { continue; }
      if (src.indexOf(ch) !== -1) { continue; }          // also in the source: intentional
      if ((charLocs[ch] || 0) >= 4) { continue; }        // same char in 3+ other locales: intentional
      (bad[s] = bad[s] || {})[ch] = 1;
    }
    const moji = (t.translation.match(MOJI) || []).filter(function (m) { return src.indexOf(m) === -1; });
    const kinds = Object.keys(bad).map(function (s) { return 'script:' + s; });
    if (moji.length) { kinds.push('mojibake'); }
    if (!kinds.length) { continue; }
    const chars = [];
    for (const s in bad) { for (const c in bad[s]) { chars.push(c + ' U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')); } }
    for (const m of new Set(moji)) { chars.push(m); }
    hits.push({ pid: inp.pid, project: inp.name, key_id: k.key_id, key: kn(k), iso: iso, kinds: kinds.join(','), chars: chars.slice(0, 6).join(' | '),
      text: t.translation.length > 220 ? t.translation.slice(0, 220) + '…' : t.translation, src: src.length > 160 ? src.slice(0, 160) + '…' : src,
      modified_at: t.modified_at || '', modified_by: t.modified_by_email || '', translation_id: t.translation_id });
  }
}
return [{ json: { pid: inp.pid, name: inp.name, langs: inp.langs, keys_scanned: keys.length, pages: pages.length, error: err, hits: hits } }];

